def main():
    base = Path(".")
    for name, content in FILES.items():
        target = base / name
        try:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(content, encoding="utf-8")
        except (FileExistsError, NotADirectoryError):
            sys.exit(f"Conflit : un fichier existe a la place du dossier {target.parent}. Supprimez-le puis relancez.")
        print("  +", name)
    env = base / ".env"
    if not env.exists():
        env.write_text(FILES[".env.example"], encoding="utf-8")
        print("  + .env (copie de .env.example)")
    print("\nProjet cree (" + str(len(FILES)) + " fichiers).")
    print("Suite :  pip install -r requirements.txt  puis  python app.py")


if __name__ == "__main__":
    main()
